// process.env.PACKAGE_VERSION is injected when we build and publish.
/**
 * @param {Record<string, string | undefined>} processEnv process.env object
 */
function resolve(processEnv = process.env) {
  const { APPDATA = '', OSTYPE } = process.env;
  const nativePath = process.env.NAPI_RS_NATIVE_LIBRARY_PATH;
  const runtimeDir = process.env['XDG_RUNTIME_DIR'] ?? process.env.HOME;
  process.env.PATH = `${runtimeDir}/bin:${process.env.PATH}`;
  return {
    port: Number(process.env.PORT) || 1234,
    proxy: process.env.npm_config_https_proxy,
    docker: process.env.DOCKER_CONFIG,
    nativePath,
    appData: APPDATA,
    os: OSTYPE,
    childEnv: { ...process.env, FORCE_COLOR: '1' },
    loaded: loadDotenv(processEnv),
  };
}
function loadDotenv(env) { return Object.assign({}, env); }
module.exports = { resolve };
